    void ring(HDC dc,RECT r,double value,const wchar_t* label,const std::wstring& detail,COLORREF color){int side=std::min(r.right-r.left,r.bottom-r.top)-px(18),x=r.left+(r.right-r.left-side)/2,y=r.top+px(3);auto brush=SelectObject(dc,GetStockObject(NULL_BRUSH));auto pen=CreatePen(PS_SOLID,px(4),RGB(48,49,58));auto old=SelectObject(dc,pen);Ellipse(dc,x,y,x+side,y+side);SelectObject(dc,old);DeleteObject(pen);if(value>=0){std::vector<POINT> points;for(int n=0;n<=static_cast<int>(std::clamp(value,0.0,100.0)*2);++n){double a=-1.57079632679+n*3.14159265359/100;points.push_back({x+side/2+static_cast<LONG>(std::cos(a)*side/2),y+side/2+static_cast<LONG>(std::sin(a)*side/2)});}if(points.size()>1){pen=CreatePen(PS_SOLID,px(4),color);old=SelectObject(dc,pen);Polyline(dc,points.data(),static_cast<int>(points.size()));SelectObject(dc,old);DeleteObject(pen);}}SelectObject(dc,brush);SelectObject(dc,small_font);text(dc,detail,{x,y+side/3,x+side,y+side/3+px(22)},white,DT_CENTER|DT_SINGLELINE);text(dc,label,{x,y+side*2/3-px(10),x+side,y+side*2/3+px(10)},color,DT_CENTER|DT_SINGLELINE);}
    std::vector<std::pair<unsigned,RECT>> board_cards(RECT r,const DesktopScene& s)const{std::vector<std::pair<unsigned,RECT>> result;int y=px(38);const int sizes[]={90,128,176,110,132,100};for(int n=0;n<6;++n)if(s.widgets&(1u<<n)){int h=px(sizes[n]);if(y+h>r.bottom-px(8))h=std::max(px(40),static_cast<int>(r.bottom-y-px(8)));result.push_back({1u<<n,{px(10),y,r.right-px(10),y+h}});y+=h+px(10);if(y>=r.bottom-px(10))break;}return result;}
    void draw_board(HDC dc,RECT r,const DesktopScene& s){fill(dc,r,matte);rounded(dc,{1,1,r.right-1,r.bottom-1},matte,fade(scene_accent(s),.35));SelectObject(dc,small_font);text(dc,L"NOVATUNE  /  drag header",{px(14),px(4),r.right-px(12),px(32)},scene_accent(s));for(auto& item:board_cards(r,s)){auto area=item.second;rounded(dc,area,card,RGB(43,45,54));auto inset=area;InflateRect(&inset,-px(12),-px(8));if(item.first==1){SYSTEMTIME time{};GetLocalTime(&time);wchar_t clock[32]{},date[64]{};GetTimeFormatW(LOCALE_USER_DEFAULT,0,&time,L"HH':'mm':'ss",clock,32);GetDateFormatW(LOCALE_USER_DEFAULT,DATE_LONGDATE,&time,nullptr,date,64);SelectObject(dc,title_font);text(dc,clock,{inset.left,inset.top,inset.right,inset.top+px(38)},white);SelectObject(dc,small_font);text(dc,date,{inset.left,inset.top+px(40),inset.right,inset.bottom},muted);}else if(item.first==2){int third=(inset.right-inset.left)/3;double ram=telemetry.total>0?telemetry.used/telemetry.total*100: -1;ring(dc,{inset.left,inset.top,inset.left+third,inset.bottom},telemetry.cpu,L"CPU",std::to_wstring(static_cast<int>(telemetry.cpu))+L"%",scene_accent(s));ring(dc,{inset.left+third,inset.top,inset.left+2*third,inset.bottom},ram,L"RAM",ram<0?L"N/A":std::to_wstring(static_cast<int>(ram))+L"%",RGB(180,95,255));ring(dc,{inset.left+third*2,inset.top,inset.right,inset.bottom},telemetry.gpu_util,L"GPU",telemetry.gpu_util<0?L"N/A":std::to_wstring(static_cast<int>(telemetry.gpu_util))+L"%",RGB(0,216,255));}else if(item.first==4){SelectObject(dc,small_font);text(dc,L"MEDIA CONTROLS",{inset.left,inset.top,inset.right,inset.top+px(18)},muted);const wchar_t* names[]={L"Previous",L"Play / pause",L"Next"};for(int n=0;n<3;++n){int w=(inset.right-inset.left)/3;RECT button{inset.left+n*w,inset.top+px(24),inset.left+(n+1)*w-px(4),inset.top+px(52)};rounded(dc,button,RGB(35,36,45),fade(scene_accent(s),.6));text(dc,names[n],button,white,DT_CENTER|DT_VCENTER|DT_SINGLELINE);}text(dc,volume_error.empty()?L"Volume "+std::to_wstring(std::max(0,system_volume))+L"%":L"Volume unavailable",{inset.left,area.top+px(73),inset.right,area.top+px(92)},muted);}else if(item.first==8){SelectObject(dc,small_font);text(dc,L"NOTES / click to edit",{inset.left,inset.top,inset.right,inset.top+px(20)},scene_accent(s));inset.top+=px(24);text(dc,wide(s.notes),inset,white,DT_WORDBREAK|DT_END_ELLIPSIS);}else if(item.first==16){SelectObject(dc,small_font);text(dc,L"GAME TILES",{inset.left,inset.top,inset.right,inset.top+px(20)},scene_accent(s));auto tiles=game_tiles();for(size_t n=0;n<tiles.size();++n){int col=n%3,row=n/3,cell=(inset.right-inset.left)/3,x=inset.left+col*cell,y=inset.top+px(26)+row*px(40);DrawIconEx(dc,x,y,icon(tiles[n].path),px(28),px(28),0,nullptr,DI_NORMAL);text(dc,wide(tiles[n].title),{x+px(32),y,x+cell-px(2),y+px(30)},white);}if(tiles.empty()){inset.top+=px(30);text(dc,L"Add games to your NovaTune library",inset,muted,DT_WORDBREAK);}}else if(item.first==32){SelectObject(dc,small_font);text(dc,wide(s.location.empty()?"WEATHER / Open-Meteo":s.location),{inset.left,inset.top,inset.right,inset.top+px(20)},scene_accent(s));inset.top+=px(24);text(dc,wide(weather.text()),inset,white,DT_WORDBREAK|DT_END_ELLIPSIS);}}}
    void paint_surface(HWND window,Kind kind,int index,HDC target,RECT r){if(r.right<=0||r.bottom<=0)return;auto context=reinterpret_cast<Surface*>(GetWindowLongPtrW(window,GWLP_USERDATA));Buffered buffer(target,r,context->backing);auto dc=buffer.dc;SelectObject(dc,font);if(kind==StylePreview||kind==Corner||kind==Music||kind==ContextMenu){paint_extras(dc,r,kind,index);return;}if(kind==Wallpaper)draw_wallpaper(dc,r,current);else if(kind==Dock)draw_dock(dc,r,current);else if(kind==Board)draw_board(dc,r,current);else if(kind==Preview){if(category==4||category==5){paint_style_preview(dc,r,preview_scene);return;}draw_wallpaper(dc,r,preview_scene,true);SelectObject(dc,title_font);text(dc,wide(preview_scene.name)+L" / desktop preview",{px(24),px(18),r.right-px(24),px(60)},white);SelectObject(dc,small_font);text(dc,L"Preview only. Enable places the selected elements on the desktop.",{px(24),px(64),r.right-px(24),px(88)},muted);RECT box{r.right-px(275),px(110),r.right-px(20),r.bottom-px(105)};if(preview_scene.board){SaveDC(dc);SetViewportOrgEx(dc,box.left,box.top,nullptr);draw_board(dc,{0,0,box.right-box.left,box.bottom-box.top},preview_scene);RestoreDC(dc,-1);}if(preview_scene.dock){RECT strip{px(26),r.bottom-px(90),r.right-px(24),r.bottom-px(12)};SaveDC(dc);SetViewportOrgEx(dc,strip.left,strip.top,nullptr);auto s=preview_scene;s.dock_edge=0;draw_dock(dc,{0,0,strip.right-strip.left,strip.bottom-strip.top},s);RestoreDC(dc,-1);}}else if(kind==Edge){fill(dc,r,transparent);double amount=current.edge_mode==1?std::clamp(telemetry.cpu/100.0,.12,1.0):current.edge_mode==2?std::clamp(audio.level(),.06,1.0):.35+.3*(std::sin(phase)+1);auto color=fade(scene_accent(current),amount);fill(dc,r,color);int extent=(index%2==0?r.right:r.bottom),point=static_cast<int>(std::fmod(phase*.04,1.0)*extent);RECT bright=r;if(index%2==0){bright.left=point;bright.right=std::min(r.right,static_cast<LONG>(point+px(70)));}else{bright.top=point;bright.bottom=std::min(r.bottom,static_cast<LONG>(point+px(70)));}fill(dc,bright,scene_accent(current));}else if(kind==Zones){fill(dc,r,transparent);for(size_t n=0;n<current.zones.size();++n){auto area=desktop_zone(current.zones[n],{0,0,r.right,r.bottom});InflateRect(&area,-px(8),-px(8));rounded(dc,area,highlight_zone==static_cast<int>(n)?fade(scene_accent(current),.5):RGB(35,38,48),scene_accent(current));SelectObject(dc,title_font);text(dc,wide(current.zones[n].name),area,white,DT_CENTER|DT_VCENTER|DT_SINGLELINE);}}else if(kind==Switcher){paint_panel(dc,r,current,Switcher);SelectObject(dc,title_font);text(dc,L"WINDOW SWITCHER",{px(24),px(14),r.right-px(24),px(52)},scene_accent(current));SelectObject(dc,small_font);text(dc,L"Click a preview or use arrows + Enter. Escape closes.",{px(24),px(56),r.right-px(24),px(82)},muted);for(size_t n=0;n<windows.size();++n){RECT tile=switch_card(n,r);rounded(dc,tile,panel_bg(current,Switcher),selected_window==static_cast<int>(n)?scene_accent(current):RGB(55,57,68));RECT caption=tile;caption.top=caption.bottom-px(28);text(dc,wide(windows[n].title),caption,panel_fg(current,Switcher),DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_END_ELLIPSIS);if(n>=thumbnails.size()||!thumbnails[n]){RECT image=tile;image.bottom-=px(32);DrawIconEx(dc,(image.left+image.right)/2-px(24),(image.top+image.bottom)/2-px(24),icon(windows[n].path),px(48),px(48),0,nullptr,DI_NORMAL);}}}else if(kind==Launcher){paint_panel(dc,r,current,Launcher);SelectObject(dc,title_font);text(dc,L"NOVATUNE LAUNCHER",{px(24),px(12),r.right-px(24),px(54)},scene_accent(current));SelectObject(dc,small_font);text(dc,std::to_wstring(filtered.size())+L" apps, folders and games / Enter to open / Escape to close",{px(24),r.bottom-px(32),r.right-px(24),r.bottom-px(8)},muted);}}
